import{_ as a,o as e,c as r,al as d}from"./chunks/framework.BawR2jEz.js";const S=JSON.parse('{"title":"Редактор","description":"Многофункциональный редактор exDoc для работы с Twig-шаблонами, SCSS-стилями и JavaScript-кодом.","frontmatter":{"title":"Редактор","description":"Многофункциональный редактор exDoc для работы с Twig-шаблонами, SCSS-стилями и JavaScript-кодом."},"headers":[],"relativePath":"editor/index.md","filePath":"editor/index.md"}'),i={name:"editor/index.md"};function o(l,t,c,n,s,h){return e(),r("div",null,[...t[0]||(t[0]=[d('<div><h1 id="редактор" tabindex="-1">Редактор <a class="header-anchor" href="#редактор" aria-label="Permalink to &quot;Редактор&quot;">​</a></h1><p>Редактор exDoc — многофункциональный инструмент для работы с шаблонами (Twig), стилями (SCSS) и JavaScript-кодом.</p><div class="tip custom-block"><p class="custom-block-title">Первый раз в редакторе?</p><p>Начните с <a href="./quick-start.html">Быстрого старта</a> — пошаговый пример создания блока с шаблоном, стилями и JavaScript.</p></div><h2 id="единыи-редактор-для-всех-сущностеи" tabindex="-1">Единый редактор для всех сущностей <a class="header-anchor" href="#единыи-редактор-для-всех-сущностеи" aria-label="Permalink to &quot;Единый редактор для всех сущностей&quot;">​</a></h2><p>Редактор встроен в формы <strong>блоков</strong>, <strong>рубрик</strong>, <strong>компонентов</strong>, <strong>шаблонов</strong> и <strong>превью рубрик</strong>. Интерфейс и набор вкладок одинаков везде — один раз разобравшись с редактором, вы работаете с ним одинаково в любой сущности.</p><p>Отличается только <strong>контекст</strong>: набор доступных Twig-функций и свойств зависит от типа сущности (блок, документ, категория). Подробнее — в <a href="./template/functions/">Справочнике Twig exDoc</a>.</p><h2 id="переменная-uniqid" tabindex="-1">Переменная uniqid <a class="header-anchor" href="#переменная-uniqid" aria-label="Permalink to &quot;Переменная uniqid&quot;">​</a></h2><p>Каждый блок, рубрика и компонент получают уникальный идентификатор <code>uniqid</code>. exDoc автоматически создаёт SCSS-переменную <code>$uniqid</code>, Twig-переменную <code>{{ uniqid }}</code> и JavaScript-переменную <code>uniqid</code> с одинаковым значением (например, <code>block-5-slider</code>).</p><p>Это позволяет связать шаблон, стили и скрипты одной сущности без конфликтов с остальными. Подробнее о применении — в полезных приёмах для <a href="./style/tips.html">стилей</a> и <a href="./javascript/tips.html">JavaScript</a>.</p><h2 id="интерфеис" tabindex="-1">Интерфейс <a class="header-anchor" href="#интерфеис" aria-label="Permalink to &quot;Интерфейс&quot;">​</a></h2><p>Редактор работает на базе CodeMirror 6 и предоставляет:</p><ul><li>Подсветку синтаксиса для HTML/Twig, SCSS и JavaScript</li><li>Автодополнение</li><li>Нумерацию строк</li><li>Форматирование кода (beautify)</li><li>Тёмную тему (One Dark)</li><li>Изменяемую высоту панели (перетаскивание)</li></ul><h2 id="вкладки" tabindex="-1">Вкладки <a class="header-anchor" href="#вкладки" aria-label="Permalink to &quot;Вкладки&quot;">​</a></h2><p>Вкладок четыре. Первая — <strong>Шаблон HTML/TWIG</strong> — разделена на три под-вкладки, в которых и пишется код сущности.</p><table tabindex="0"><thead><tr><th>Вкладка</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Шаблон HTML/TWIG</strong></td><td>Код сущности — см. под-вкладки ниже</td></tr><tr><td><a href="./links/">Связи</a></td><td>Подключение внешних CSS- и JS-файлов</td></tr><tr><td><a href="./language/">Языки</a></td><td>Мультиязычные переменные для шаблона</td></tr><tr><td><a href="./helper/">Помощь</a></td><td>Быстрая вставка функций, полей, компонентов и иконок</td></tr></tbody></table><p><strong>Под-вкладки «Шаблон HTML/TWIG»</strong></p><table tabindex="0"><thead><tr><th>Под-вкладка</th><th>Описание</th></tr></thead><tbody><tr><td><a href="./template/">TWIG</a></td><td>Twig-шаблон сущности — разметка, логика, вывод полей</td></tr><tr><td><a href="./style/">SCSS</a></td><td>SCSS-стили с переменными, миксинами и изоляцией через <code>uniqid</code></td></tr><tr><td><a href="./javascript/">JS</a></td><td>Клиентский JS-код с изоляцией через IIFE</td></tr></tbody></table><p>Под-вкладки SCSS и JS появляются, только если у сущности включены соответствующие статусы. Если вкладки JS не видно — значит скрипты для этой сущности выключены; включите статус, и она появится рядом с TWIG.</p><p>В каждой под-вкладке есть свой экстрактор — кнопка, генерирующая заготовку по полям сущности. Их описание в <a href="./template/">TWIG</a>, <a href="./style/">SCSS</a> и <a href="./javascript/">JS</a>.</p><h2 id="горячие-клавиши" tabindex="-1">Горячие клавиши <a class="header-anchor" href="#горячие-клавиши" aria-label="Permalink to &quot;Горячие клавиши&quot;">​</a></h2><p>CodeMirror поддерживает стандартные сочетания:</p><ul><li><code>Ctrl+Z</code> / <code>Cmd+Z</code> — отмена</li><li><code>Ctrl+Shift+Z</code> / <code>Cmd+Shift+Z</code> — повтор</li><li><code>Ctrl+F</code> / <code>Cmd+F</code> — панель поиска; замена включается переключателем в самой панели</li><li><code>Ctrl+G</code> / <code>Cmd+G</code> — следующее совпадение</li><li><code>Ctrl+D</code> / <code>Cmd+D</code> — выделить следующее такое же слово</li><li><code>Tab</code> — отступ</li></ul><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./../blocks/">Блоки</a> — использование редактора в блоках</li><li><a href="./../fast-settings/">Быстрые настройки</a> — глобальные переменные и стили</li></ul></div>',1)])])}const u=a(i,[["render",o]]);export{S as __pageData,u as default};
